UPDATE order_return_check SET remaining_close_ms=TIMESTAMPDIFF(MICROSECOND,#{at},auto_close_at) DIV 1000,
    auto_close_at=NULL,claim_created=1,check_status='claim_submitted',version=version+1,updated_at=#{at}
    WHERE id=#{check} AND closed_at IS NULL AND claim_created=0 AND check_status IN ('pending','warning') AND check_start_at<=#{at} AND auto_close_at>#{at}
